    // @port: Daqifi.Desktop.ViewModels.ProfilesPaneViewModel.ShowError
    private void ShowError(Profile profile, string message)
    {
        SelectedProfile = profile;
        IsNewProfile = false;
        IsDrawerOpen = true;
        DrawerError = message;
    }

    // @port: Daqifi.Desktop.ViewModels.ProfilesPaneViewModel.DeleteProfile
    private void DeleteProfile(Profile? profile)
    {
        if (profile == null) return;

        if (LoggingManager.Instance.Active)
        {
            DrawerError = "Cannot delete a profile while logging is active.";
            return;
        }

        if (profile.IsProfileActive || Profiles.Any(p => p.IsProfileActive))
        {
            DrawerError = "Deactivate the profile before deleting it.";
            return;
        }

        // Drop the pending edit before closing rather than writing it back: this profile is being
        // deleted, so persisting it first is work that can only fail for nothing.
        SelectedProfile = null;
        CloseDrawer();

        if (!LoggingManager.Instance.UnsubscribeProfile(profile))
        {
            ShowError(profile, ProfileWriteFailureMessage("delete this profile"));
        }
    }

    // @port: Daqifi.Desktop.ViewModels.ProfilesPaneViewModel.SaveNewProfile
    private void SaveNewProfile()
    {
        if (!CanSaveNewProfile()) return;

        var now = DateTime.Now;
        var profile = new Profile
        {
            Name = NewProfileName.Trim(),
            ProfileId = Guid.NewGuid(),
            CreatedOn = now,
            Devices = [],
        };

        foreach (var deviceItem in NewDeviceItems.Where(d => d.IsSelected))
        {
            var device = deviceItem.Device;
            var pd = new ProfileDevice
            {
                DeviceName = device.Name,
                DevicePartName = device.DevicePartNumber,
                DeviceSerialNo = device.DeviceSerialNo,
                MacAddress = device.MacAddress,
                SamplingFrequency = NewProfileFrequency,
                Channels = [],
            };

            foreach (var channelItem in deviceItem.ChannelItems.Where(c => c.IsSelected))
            {
                pd.Channels.Add(new ProfileChannel
                {
                    Name = channelItem.Channel.Name,
                    Type = channelItem.Channel.TypeString,
                    IsChannelActive = true,
                    SerialNo = channelItem.Channel.DeviceSerialNo,
                });
            }

            profile.Devices.Add(pd);
        }

        if (!LoggingManager.Instance.SubscribeProfile(profile))
        {
            DrawerError = ProfileWriteFailureMessage("save this profile");
            return;
        }

        CloseDrawer();
    }

    // @port: Daqifi.Desktop.ViewModels.ProfilesPaneViewModel.SaveCurrentSettings
    private void SaveCurrentSettings()
    {
        var connected = ConnectionManager.Instance.ConnectedDevices.ToList();
        if (connected.Count == 0)
        {
            DrawerError = "No devices connected.";
            return;
        }

        var now = DateTime.Now;
        var name = string.IsNullOrWhiteSpace(NewProfileName)
            ? $"DAQiFi Profile {now:M/d/yyyy h:mm tt}"
            : NewProfileName.Trim();
        var profile = new Profile
        {
            Name = name,
            ProfileId = Guid.NewGuid(),
            CreatedOn = now,
            Devices = [],
        };

        foreach (var device in connected)
        {
            if (device.DataChannels.Count == 0) continue;
            var pd = new ProfileDevice
            {
                DeviceName = device.Name,
                DevicePartName = device.DevicePartNumber,
                DeviceSerialNo = device.DeviceSerialNo,
                MacAddress = device.MacAddress,
                SamplingFrequency = device.StreamingFrequency,
                Channels = device.DataChannels
                    .Where(c => c.IsActive)
                    .Select(c => new ProfileChannel
                    {
                        Name = c.Name,
                        Type = c.TypeString,
                        IsChannelActive = true,
                        SerialNo = c.DeviceSerialNo,
                    })
                    .ToList(),
            };
            profile.Devices.Add(pd);
        }

        if (!LoggingManager.Instance.SubscribeProfile(profile))
        {
            DrawerError = ProfileWriteFailureMessage("save this profile");
            return;
        }

        CloseDrawer();
    }

    /// <summary>
    /// What the drawer says when a profile could not be written. The pane used to say nothing at
    /// all: the write failed, the drawer closed, and the profile sat in the list looking saved
    /// until the next launch removed it (#184).
    /// </summary>
    private static string ProfileWriteFailureMessage(string attempt) =>
        $"Could not {attempt} — the profiles file could not be written. " +
        "Check that you have permission to write it and that the disk is not full, then try again.";

    /// <summary>
    /// The one-shot notice about a damaged profiles file, shown the first time the drawer opens
    /// after one was moved aside; empty the rest of the time, which is every other open.
    /// </summary>
    private static string ProfileRecoveryNotice() =>
        LoggingManager.Instance.TakeProfileRecoveryNotice() ?? string.Empty;
    #endregion

    #region Helpers
    // @port: Daqifi.Desktop.ViewModels.ProfilesPaneViewModel.RefreshActiveProfileName
    private void RefreshActiveProfileName() =>
        ActiveProfileName = Profiles.FirstOrDefault(p => p.IsProfileActive)?.Name;

    // @port: Daqifi.Desktop.ViewModels.ProfilesPaneViewModel.CanSaveNewProfile
    private bool CanSaveNewProfile() =>
        !string.IsNullOrWhiteSpace(NewProfileName) &&
        NewDeviceItems.Any(d => d.IsSelected) &&
        NewProfileFrequency > 0;
    #endregion

    #region Cleanup
    /// <summary>
    /// Detaches every event handler the view model subscribed to and releases
    /// any pending confirm-dialog awaiter. Call when the hosting view unloads.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ProfilesPaneViewModel.Cleanup
    public void Cleanup()
    {
        LoggingManager.Instance.PropertyChanged -= OnLoggingManagerPropertyChanged;
        Profiles.CollectionChanged -= OnProfilesCollectionChanged;
        foreach (var p in Profiles) p.PropertyChanged -= OnProfilePropertyChanged;
        foreach (var item in NewDeviceItems)
            item.PropertyChanged -= OnNewDeviceItemPropertyChanged;
        // Release any awaiter on an unresolved confirm dialog.
        ConfirmOverlay.Cancel();
    }
    #endregion
